@import "@fontsource-variable/roboto";
@import "@fontsource-variable/roboto-condensed";
@import "@fontsource-variable/roboto-mono";

/* Light: the faithful mode. White page, #f4f4f4 grey bands and cards, black ink, #202020
   button text, warm orange #faaf40 for hairlines, outlines, badges and hovers. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(0.967 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.807 0.149 72.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.967 0 0);
  --secondary-foreground: oklch(0.244 0 0);
  --muted: oklch(0.885 0 0);
  --muted-foreground: oklch(0.545 0 0);
  --accent: oklch(0.807 0.149 72.8 / 12%);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.894 0 0);
  --input: oklch(0.798 0 0);
  --ring: oklch(0.807 0.149 72.8);
  --highlight: oklch(0.807 0.149 72.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.807 0.149 72.8);
  --chart-1: oklch(0.807 0.149 72.8);
  --chart-2: oklch(0.244 0 0);
  --chart-3: oklch(0.545 0 0);
  --chart-4: oklch(0.7 0.12 60);
  --chart-5: oklch(0.885 0 0);
  --sidebar: oklch(0.967 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.807 0.149 72.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.807 0.149 72.8 / 12%);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.894 0 0);
  --sidebar-ring: oklch(0.807 0.149 72.8);

  --typeface-body: "Roboto Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Roboto Condensed Variable", "Roboto Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Roboto Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  --page-width: 84.75rem;
  --page-gutter: 1.875rem;
  --section-y: 2.375rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 6.875rem;
  }
}

/* Dark: the sibling, and what the hero, hiring and footer bands use as `.dark` scopes.
   Black page (the original's footer), #1e1e1e bands and cards, white ink, the same orange,
   #202020 hairlines. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.235 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.178 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.807 0.149 72.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.178 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.321 0 0);
  --muted-foreground: oklch(0.798 0 0);
  --accent: oklch(0.807 0.149 72.8 / 14%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.244 0 0);
  --input: oklch(0.405 0 0);
  --ring: oklch(0.807 0.149 72.8);
  --highlight: oklch(0.807 0.149 72.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.807 0.149 72.8);
  --chart-1: oklch(0.807 0.149 72.8);
  --chart-2: oklch(0.925 0 0);
  --chart-3: oklch(0.545 0 0);
  --chart-4: oklch(0.7 0.12 60);
  --chart-5: oklch(0.405 0 0);
  --sidebar: oklch(0.178 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.807 0.149 72.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.807 0.149 72.8 / 14%);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(0.244 0 0);
  --sidebar-ring: oklch(0.807 0.149 72.8);
}
